b:if.b:skin:
 /* 
  =============================================
  THE BUKIT BESI BLOG — OPTIMIZED THEME v2026.07
  Pro enhancements applied:
  - Updated jQuery 3.7.1 + defer for better INP
  - Full NewsArticle JSON-LD for Google News/Discover
  - Strengthened CLS prevention for ad slots
  - AUTO ADS OPTIMIZED: Disabled redundant manual ad sections (post-ads-1,2,4).
    Only kept strategic In-Article manual placement. Rely on Google Auto Ads for density.
  - Performance & SEO hardening
  =============================================
*/ /* Blogger Template Style */
/*-- Customize Options (Start) --
<Variable name="keycolor" description="Main Color" type="color" default="#2563eb" value="#2563eb"/>
<Group description="Layout Options" selector="body">
    <Variable name="boxedMode" description="Enable Boxed Mode" type="length" default="0px" min="0px" max="1px" value="0px"/>
    <Variable name="stickyMenu" description="Enable Sticky Header" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="stickySidebar" description="Enable Sticky Sidebar" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Fonts" selector="body">
    <Variable name="main.font" description="Main Font" type="font" family="Inter" default="normal 400 14px $(family)" value="normal 400 14px $(family)"/>
    <Variable name="title.font" description="Title Font" type="font" family="Inter" default="normal 400 14px $(family)" value="normal 400 14px $(family)"/>
    <Variable name="text.font" description="Text Font" type="font" family="Inter" default="normal 400 14px $(family)" value="normal 400 14px $(family)"/>
</Group>
<Group description="Background" selector="body">
    <Variable name="background.color" description="Body Background (Boxed)" type="color" default="#f3f4f6"  value="#f3f4f6"/>
    <Variable name="outer.bg" description="Outer Background" type="color" default="#ffffff"  value="#ffffff"/>
    <Variable name="modal.bg" description="Modal Background" type="color" default="#ffffff" value="#ffffff"/>
    <Variable name="gray" description="Gray Background" type="color" default="#f3f4f6"  value="#f3f4f6"/>
    <Variable name="border" description="Border Color" type="color" default="$(gray)"  value="#f3f4f6"/>
</Group>
<Group description="Colors" selector="body">
    <Variable name="accent.color" description="Accent Color" type="color" default="#2563eb" value="#2563eb"/>
    <Variable name="title.color" description="Title Color" type="color" default="#111827" value="#111827"/>
    <Variable name="title.hover.color" description="Title Hover Color" type="color" default="$(accent.color)" value="#2563eb"/>
    <Variable name="text.color" description="Text Color" type="color" default="#4b5563"  value="#4b5563"/>
    <Variable name="summary.color" description="Summary Color" type="color" default="#6b7280" value="#6b7280"/>
    <Variable name="meta.color" description="Meta Color" type="color" default="#9ca3af" value="#9ca3af"/>
</Group>
<Group description="Header" selector=".site-header">
    <Variable name="header.bg" description="Background" type="color" default="#ffffff" value="#ffffff"/>
    <Variable name="header.color" description="Color" type="color" default="$(title.color)" value="#111827"/>
    <Variable name="header.hover.color" description="Hover Color" type="color" default="$(accent.color)" value="#2563eb"/>
</Group>
<Group description="Sub Menu" selector=".site-header">
    <Variable name="submenu.bg" description="Background" type="color" default="#111827" value="#111827"/>
    <Variable name="submenu.color" description="Color" type="color" default="#f9fafb" value="#f9fafb"/>
    <Variable name="submenu.hover.color" description="Hover Color" type="color" default="$(accent.color)" value="#2563eb"/>
</Group>
<Group description="Blog Posts" selector="#main">
    <Variable name="gridStyle" description="Enable Grid Style" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="postSummary" description="Show Summary" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="postCategory" description="Show Category" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Post Page" selector="body">
    <Variable name="breadcrumb" description="Show Breadcrumbs" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="postnav" description="Show Navigation" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="postSidebar" description="Show Sidebar" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Static Page" selector="body">
    <Variable name="pageHeaderAds" description="Show Header Ads" type="length" default="0px" min="0px" max="1px" value="1px"/>
    <Variable name="pageSidebar" description="Show Sidebar" type="length" default="0px" min="0px" max="1px" value="0px"/>
    <Variable name="pageFooterAds" description="Show Footer Ads" type="length" default="0px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Footer" selector=".site-footer .footer">
    <Variable name="footer.bg" description="Background" type="color" default="#111827" value="#111827"/>
    <Variable name="footer.color" description="Color" type="color" default="#f9fafb" value="#f9fafb"/>
    <Variable name="footer.hover.color" description="Hover Color" type="color" default="$(accent.color)" value="#2563eb"/>
    <Variable name="footer.text.color" description="Text Color" type="color" default="#d1d5db" value="#d1d5db"/>
</Group>
<Group description="Footer Bar" selector=".footer-bar">
    <Variable name="footerbar.bg" description="Background" type="color" default="#020617" value="#020617"/>
    <Variable name="footerbar.color" description="Color" type="color" default="#f9fafb" value="#f9fafb"/>
    <Variable name="footerbar.hover.color" description="Hover Color" type="color" default="$(accent.color)" value="#2563eb"/>
</Group>
<Group description="Dark Mode" selector="body">
    <Variable name="darkMode" description="Enable Native Dark Mode" type="length" default="0px" min="0px" max="1px" value="0px"/>
    <Variable name="userDarkMode" description="Enable User Dark Mode (Toggle)" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="dark.bg1" description="Dark Background 1" type="color" default="#374151" value="#374151"/>
    <Variable name="dark.bg2" description="Dark Background 2" type="color" default="#1f2937" value="#1f2937"/>
    <Variable name="dark.bg3" description="Dark Background 3" type="color" default="#111827" value="#111827"/>
    <Variable name="dark.bg4" description="Dark Background 4" type="color" default="#030712" value="#030712"/>
    <Variable name="dark.accent.color" description="Accent Color" type="color" default="$(accent.color)" value="#2563eb"/>
    <Variable name="dark.title" description="Title Color" type="color" default="#f9fafb" value="#f9fafb"/>
    <Variable name="dark.text" description="Text Color" type="color" default="#d1d5db" value="#d1d5db"/>
    <Variable name="dark.meta" description="Meta Color" type="color" default="#9ca3af" value="#9ca3af"/>
</Group>
<Group description="Miscellaneous" selector="body">
    <Variable name="rgba" description="RGBA Key (Overlay)" type="color" default="#111827"  value="#111827"/>
    <Variable name="browser.bg" description="Browser Tab Background" type="color" default="#111827"  value="#111827"/>
</Group>
<Variable name="body.background" description="Background" type="background" color="$(background.color)" default="$(color) none repeat fixed top left" value="$(color) none repeat fixed top left"/>
<Variable name="body.background.color" description="Comments Background" hideEditor="true" type="color" default="transparent"  value="transparent"/>
<Variable name="body.title.color" description="Comments Color" hideEditor="true" type="color" default="$(title.color)" value="#111827"/>
<Variable name="body.text.color" description="Comments Text Color" hideEditor="true" type="color" default="$(text.color)"  value="#4b5563"/>
<Variable name="body.link.color" description="Comments Link Color" hideEditor="true" type="color" default="$(accent.color)"  value="#2563eb"/>
<Variable name="body.text.font" description="Comments Font 1" hideEditor="true" type="font" default="normal 400 16px inter, roboto, sans-serif !important"  value="normal 400 16px inter, roboto, sans-serif !important"/>
<Variable name="body.action.font.large" description="Comments Font 2" hideEditor="true" type="font" default="normal 700 16px inter, roboto, sans-serif !important"  value="normal 700 16px inter, roboto, sans-serif !important"/>
-- Customize Options (End) --*/

/*-- CSS Variables --*/
:root{
--body-font:$(main.font.family), sans-serif;
--menu-font:$(main.font.family), sans-serif;
--title-font:$(title.font.family), sans-serif;
--text-font:$(text.font.family), sans-serif;
--icon-font:"bootstrap-icons", bootstrap-icons;
--body-bg-color:$(background.color);
--body-bg:$(body.background);
--outer-bg:$(outer.bg);
--accent-color:$(accent.color);
--accent-color-lite:$(accent.color)80;
--white-color:#ffffff;
--title-color:$(title.color);
--title-hover-color:$(title.hover.color);
--text-color:$(text.color);
--summary-color:$(summary.color);
--meta-color:$(meta.color);
--header-bg:$(header.bg);
--header-color:$(header.color);
--header-hover-color:$(header.hover.color);
--submenu-bg:$(submenu.bg);
--submenu-color:$(submenu.color);
--submenu-hover-color:$(submenu.hover.color);
--submenu-gray-bg:$(submenu.color)0d;
--footer-bg:$(footer.bg);
--footer-color:$(footer.color);
--footer-hover-color:$(footer.hover.color);
--footer-text-color:$(footer.text.color);
--footer-gray-bg:$(footer.color)0d;
--footerbar-bg:$(footerbar.bg);
--footerbar-color:$(footerbar.color);
--footerbar-hover-color:$(footerbar.hover.color);
--btn-bg:var(--accent-color);
--btn-color:var(--white-color);
--modal-bg:$(modal.bg);
--header:4.5rem;
--logo:2.5rem;
--container:60.625rem;
--sidebar:18.75rem;
--gap:2.25rem;
--aspect-ratio: 16/9;
--title-weight:700;
--letter-spacing:-0.005em;
--line-clamp:3;
--gray-bg:$(gray);
--border-color:$(border);
--rgba: $(rgba);
--rgba-05: $(rgba)05;
--rgba-08: $(rgba)08;
--rgba-0d: $(rgba)0d;
--rgba-e6: $(rgba)e6;
--rgba-1a: $(rgba)1a;
--rgba-33: $(rgba)33;
--rgba-99: $(rgba)99;
--shadow:0 1px 2px var(--rgba-05),0 10px 15px -3px var(--rgba-08);
--radius:0.25rem;
}

html.is-dark{
--body-bg-color:$(dark.bg1);
--outer-bg:$(dark.bg2);
--accent-color:$(dark.accent.color);
--accent-color-lite:$(dark.accent.color)80;
--title-color:$(dark.title);
--title-hover-color:$(dark.accent.color);
--text-color:$(dark.text);
--summary-color:$(dark.text);
--meta-color:$(dark.meta);
--header-bg:$(dark.bg3);
--header-color:$(dark.title);
--header-hover-color:$(dark.accent.color);
--submenu-bg:$(dark.bg4);
--submenu-color:$(dark.title);
--submenu-hover-color:$(dark.accent.color);
--submenu-gray-bg:rgba(255,255,255,.03);
--footer-bg:$(dark.bg3);
--footer-color:$(dark.title);
--footer-hover-color:$(dark.accent.color);
--footer-text-color:$(dark.text);
--footer-gray-bg:rgba(255,255,255,.03);
--footerbar-bg:$(dark.bg4);
--footerbar-color:$(dark.title);
--footerbar-hover-color:$(dark.accent.color);
--modal-bg:$(dark.bg1);
--gray-bg:rgba(255,255,255,.03);
--border-color:rgba(255,255,255,.03);
--rgba: $(dark.bg3);
--rgba-05: $(dark.bg3)05;
--rgba-08: $(dark.bg3)08;
--rgba-0d: $(dark.bg3)0d;
--rgba-e6: $(dark.bg3)e6;
--rgba-1a: $(dark.bg3)1a;
--rgba-33: $(dark.bg3)33;
--rgba-99: $(dark.bg3)99;
--shadow:0 1px 2px var(--rgba-0d),0 10px 15px -3px var(--rgba-33);
}

html.rtl{
--body-font:Cairo, sans-serif;
--menu-font:Cairo, sans-serif;
--title-font:Cairo, sans-serif;
--text-font:Cairo, sans-serif;
}
ins.adsbygoogle[data-ad-status="unfilled"] {display:none !important;}
.inline-ad:empty, .post-ads-1:empty, .post-ads-2:empty, .post-ads-3:empty, .post-ads-4:empty, .content-ads:empty {display:none !important; margin:0 !important; padding:0 !important;}
.related-wrap .widget-content:empty {display:none !important;}
/*-- {getCard} internal-link card (BACA JUGA) --*/
.tb-card-box{display:flex;align-items:center;gap:12px;background:#f8fafc;border:1px solid #e2e8f0;border-left:4px solid #0284c7;padding:12px 16px;margin:22px 0;border-radius:6px;box-shadow:0 1px 2px rgba(0,0,0,.04);contain:content}
.tb-card-badge{background:#0284c7;color:#fff;font-size:.72rem;font-weight:700;letter-spacing:.05em;padding:4px 8px;border-radius:4px;white-space:nowrap;flex-shrink:0}
.tb-card-title{color:#0f172a;font-size:.95rem;font-weight:600;text-decoration:none;line-height:1.4;transition:color .15s ease}
.tb-card-title:hover{color:#0284c7;text-decoration:underline}
html.is-dark .tb-card-box{background:var(--gray-bg);border-color:var(--border-color);border-left-color:#0284c7}
html.is-dark .tb-card-title{color:var(--title-color)}
@media (max-width:640px){.tb-card-box{flex-direction:column;align-items:flex-start;gap:8px;padding:10px 14px}}
/*-- Built-in Blogger comments: always visible (tbb-style.css hides them until .visible is set) --*/
.post-footer .blog-post-comments{display:flex}

b:if.script:
//
(function(){
  'use strict';
  // {getCard} $title={...}  ->  BACA JUGA card (same markup as the previous theme)
  document.querySelectorAll('.post-body a').forEach(function(link){
    var text = link.textContent || '';
    if (text.indexOf('{getCard}') === -1) return;
    var m = text.match(/\$title=\{([^}]+)\}/);
    var card = document.createElement('aside');
    card.className = 'tb-card-box';
    var badge = document.createElement('span');
    badge.className = 'tb-card-badge';
    badge.textContent = 'BACA JUGA';
    var a = document.createElement('a');
    a.className = 'tb-card-title';
    a.href = link.getAttribute('href') || '#';
    if (link.getAttribute('target')) a.target = link.getAttribute('target');
    a.textContent = m ? m[1].trim() : 'Baca Selanjutnya';
    card.appendChild(badge);
    card.appendChild(a);
    var parent = link.parentElement;
    var target = (parent && /^(B|STRONG)$/.test(parent.tagName)) ? parent : link;
    target.parentNode.replaceChild(card, target);
  });
  // Built-in Blogger comments: show the section and open the comment form
  document.querySelectorAll('.blog-post-comments').forEach(function(wrap){
    var m = (wrap.getAttribute('data-shortcode') || '').match(/\$type=\{([^}]*)\}/i);
    var type = m ? m[1].trim().toLowerCase() : 'blogger';
    wrap.classList.add('visible');
    if (type !== 'blogger') return;
    wrap.classList.add('blogger-comments', 'cf-on');
    wrap.querySelectorAll('.show-cf').forEach(function(b){ b.hidden = true; });
    var top = wrap.querySelector('#top-continue .comment-reply');
    if (top) top.classList.add('btn');
  });
})();
//

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
	document.body.addEventListener('click', function(e) {
		var shareBtn = e.target.closest('.share-toggle');
		if(shareBtn) {
			e.preventDefault();
			// Use native mobile share API if available (faster, better UX)
			if(navigator.share) {
				navigator.share({
					title: document.title,
					url: window.location.href
				}).catch(function(err) {
					console.log('Share failed:', err);
				});
			} else {
				// Fallback to theme modal for Desktop
				var modal = document.querySelector('.share-modal');
				if(modal) {
					modal.style.display = 'flex';
					modal.style.opacity = '1';
					modal.style.visibility = 'visible';
				}
			}
		}
		var closeBtn = e.target.closest('.hide-modal');
		if(closeBtn) {
			e.preventDefault();
			var modal = document.querySelector('.share-modal');
			if(modal) {
				modal.style.display = 'none';
				modal.style.opacity = '0';
				modal.style.visibility = 'hidden';
			}
		}
	});
});
//
